def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_opp = history[-1]

    opp_defects = 0
    for h in history:
        if h[1] == 'D':
            opp_defects += 1

    opp_coops = n - opp_defects
    opp_coop_rate = opp_coops / n

    recent = min(8, n)
    recent_opp_defects = 0
    for h in history[-recent:]:
        if h[1] == 'D':
            recent_opp_defects += 1
    recent_opp_coops = recent - recent_opp_defects

    opp_streak = 0
    for h in reversed(history):
        if h[1] == 'D':
            opp_streak += 1
        else:
            break

    lenient = 0
    punish = 0
    recent_lenient = 0
    recent_punish = 0
    resp_start = max(0, n - 16)

    for i in range(n - 1):
        if history[i][0] == 'D':
            if history[i + 1][1] == 'C':
                lenient += 1
                if i >= resp_start:
                    recent_lenient += 1
            else:
                punish += 1
                if i >= resp_start:
                    recent_punish += 1

    pure = (opp_defects == 0)
    cooperative_now = (opp_coop_rate > 0.65 and recent_opp_defects <= 2)
    very_coop = (opp_coop_rate > 0.85 and recent_opp_defects <= 1)
    clean_recent = (recent_opp_defects == 0)

    start_exploit = False
    if pure:
        start_exploit = True
    if not pure:
        if opp_coop_rate > 0.95 and clean_recent and punish == 0 and n <= 90:
            start_exploit = True
        elif recent_lenient > 0 and recent_punish == 0 and cooperative_now:
            start_exploit = True
        elif lenient > punish and lenient >= 2 and cooperative_now and recent_punish == 0:
            start_exploit = True
        elif lenient >= 1 and punish == 1 and opp_coop_rate > 0.8 and clean_recent:
            start_exploit = True
        elif n >= 12 and n <= 85 and lenient == 0 and punish == 1 and clean_recent and opp_coop_rate > 0.4:
            start_exploit = True

    cont_exploit = False
    if pure and lenient >= 1:
        cont_exploit = True
    elif lenient >= 1 and punish == 0 and (very_coop or (clean_recent and opp_coop_rate > 0.8)):
        cont_exploit = True
    elif recent_lenient > 0 and recent_punish == 0 and cooperative_now:
        cont_exploit = True
    elif lenient > punish and lenient >= 2 and cooperative_now and recent_punish == 0:
        cont_exploit = True
    elif lenient >= 1 and punish <= 1 and very_coop and clean_recent:
        cont_exploit = True

    if last_opp == 'D':
        if last_my == 'D':
            if opp_coops > 0 and opp_coop_rate > 0.5 and opp_streak <= 4:
                return 'C'
            if recent_opp_defects <= 2 and opp_coop_rate > 0.35:
                return 'C'
            if lenient > punish and lenient >= 2 and opp_streak <= 2:
                return 'C'
            if lenient >= 1 and punish <= 1 and recent_opp_coops > 0 and opp_streak <= 2:
                return 'C'
            return 'D'
        else:
            if opp_coops > 0 and opp_coop_rate > 0.55 and opp_streak <= 2 and recent_opp_defects <= 3:
                return 'C'
            if lenient > punish and lenient >= 2 and opp_streak <= 2:
                return 'C'
            if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'C' and opp_coop_rate > 0.35:
                return 'C'
            return 'D'

    else:
        if last_my == 'D':
            if cont_exploit:
                return 'D'
            return 'C'
        if start_exploit:
            return 'D'
        return 'C'
